from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Reduce over dim=1 for a 3D tensor of shape (B, D1, D2)
// Output shape (B, D2)
// Two-stage reduction: the D1 dimension is partitioned into D1_NPARTS
// independent chunks that are reduced in parallel by separate CTAs
// (the reduction dimension is distributed across the grid's z axis).
// This multiplies the number of concurrently schedulable blocks by
// D1_NPARTS, greatly increasing the amount of independent work available
// to the GPU scheduler and improving memory-level parallelism / SM
// occupancy for the large D1=4096 reduction. A second, tiny kernel
// finishes the reduction over the small (D1_NPARTS) partial results.
#define COLS_PER_THREAD 8
#define D1_NPARTS 16
__global__ void max_reduce_dim1_partial_kernel(const float* __restrict__ x,
                                                float* __restrict__ partial,
                                                int B, int D1, int D2,
                                                int part_size,
                                                int grid_y, int nparts,
                                                int total_work) {
    int chunk = blockDim.x * COLS_PER_THREAD;
    // Grid-stride loop over a linearized (b, col_chunk, part) work space.
    // The number of launched blocks is capped to the device's concurrent
    // capacity (numSMs * maxActiveBlocksPerSM) so that the grid consists
    // of full waves with no partial tail wave, avoiding the tail-effect
    // slowdown seen when launching one block per (b, col_chunk, part).
    for (int linear = blockIdx.x; linear < total_work; linear += gridDim.x) {
        int b = linear / (grid_y * nparts);
        int rem = linear - b * (grid_y * nparts);
        int col_chunk_idx = rem / nparts;
        int part = rem % nparts;
        int d1_start = part * part_size;
        int d1_end = d1_start + part_size;
        if (d1_end > D1) d1_end = D1;
        int col_start = col_chunk_idx * chunk + threadIdx.x;
        if (d1_start >= d1_end) {
            // Nothing to reduce for this (rare, tail) part; still need to
            // write -inf so the finalize kernel behaves correctly.
            float* out_row0 = partial + ((size_t)b * nparts + part) * D2;
            #pragma unroll
            for (int k = 0; k < COLS_PER_THREAD; ++k) {
                int c = col_start + k * blockDim.x;
                if (c < D2) out_row0[c] = -FLT_MAX;
            }
            continue;
        }
        int cols[COLS_PER_THREAD];
        float max_val[COLS_PER_THREAD];
        #pragma unroll
        for (int k = 0; k < COLS_PER_THREAD; ++k) {
            cols[k] = col_start + k * blockDim.x;
            max_val[k] = -FLT_MAX;
        }
        bool full = (cols[COLS_PER_THREAD - 1] < D2);
        const float* base = x + (size_t)b * D1 * D2;
        size_t strideD2 = (size_t)D2;
        if (full) {
            #pragma unroll 4
            for (int i = d1_start; i < d1_end; ++i) {
                const float* row = base + (size_t)i * strideD2;
                #pragma unroll
                for (int k = 0; k < COLS_PER_THREAD; ++k) {
                    float v = __ldg(&row[cols[k]]);
                    max_val[k] = fmaxf(max_val[k], v);
                }
            }
            float* out_row = partial + ((size_t)b * nparts + part) * D2;
            #pragma unroll
            for (int k = 0; k < COLS_PER_THREAD; ++k) {
                out_row[cols[k]] = max_val[k];
            }
        } else {
            #pragma unroll 4
            for (int i = d1_start; i < d1_end; ++i) {
                const float* row = base + (size_t)i * strideD2;
                #pragma unroll
                for (int k = 0; k < COLS_PER_THREAD; ++k) {
                    if (cols[k] < D2) {
                        float v = __ldg(&row[cols[k]]);
                        max_val[k] = fmaxf(max_val[k], v);
                    }
                }
            }
            float* out_row = partial + ((size_t)b * nparts + part) * D2;
            #pragma unroll
            for (int k = 0; k < COLS_PER_THREAD; ++k) {
                if (cols[k] < D2) {
                    out_row[cols[k]] = max_val[k];
                }
            }
        }
    }
}
// Finalize kernel: reduce the small D1_NPARTS-sized partial-max buffer
// down to the final (B, D2) output. This second pass is very cheap
// (only nparts elements per output) compared to the first pass.
__global__ void max_reduce_dim1_finalize_kernel(const float* __restrict__ partial,
                                                 float* __restrict__ out,
                                                 int B, int D2, int nparts) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * D2;
    if (idx >= total) return;
    int b = idx / D2;
    int col = idx % D2;
    const float* p = partial + (size_t)b * nparts * D2 + col;
    float max_val = -FLT_MAX;
    #pragma unroll
    for (int i = 0; i < nparts; ++i) {
        float v = p[(size_t)i * D2];
        max_val = fmaxf(max_val, v);
    }
    out[idx] = max_val;
}
// Reduce over dim=0 for a 3D tensor of shape (D0, D1, D2)
// Output shape (D1, D2)
__global__ void max_reduce_dim0_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int D0, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = D1 * D2;
    if (idx >= total) return;
    const float* base = x + idx;
    float max_val = -FLT_MAX;
    size_t stride = (size_t)D1 * D2;

    for (int i = 0; i < D0; ++i) {
        float val = base[(size_t)i * stride];
        max_val = val > max_val ? val : max_val;
    }

    out[idx] = max_val;
}

// Reduce over dim=2 (last dim) for a 3D tensor of shape (D0, D1, D2)
// Output shape (D0, D1)
__global__ void max_reduce_dim2_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int D0, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = D0 * D1;
    if (idx >= total) return;

    const float* base = x + (size_t)idx * D2;
    float max_val = -FLT_MAX;

    for (int i = 0; i < D2; ++i) {
        float val = base[i];
        max_val = val > max_val ? val : max_val;
    }

    out[idx] = max_val;
}

torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "Input must be a 3D tensor");
    x = x.contiguous();

    int D0 = x.size(0);
    int D1 = x.size(1);
    int D2 = x.size(2);

    torch::Tensor out;

    if (dim == 1) {
        out = torch::empty({D0, D2}, x.options());
        int threads = 256;
        int chunk = threads * COLS_PER_THREAD;
        int nparts = D1_NPARTS;
        if (nparts > D1) nparts = D1;
        int part_size = (D1 + nparts - 1) / nparts;
        auto partial = torch::empty({D0, nparts, D2}, x.options());
        int grid_y = (D2 + chunk - 1) / chunk;
        int total_work = D0 * grid_y * nparts;
        int device = 0;
        cudaGetDevice(&device);
        int numSMs = 0;
        cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
        int maxBlocksPerSM = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &maxBlocksPerSM, max_reduce_dim1_partial_kernel, threads, 0);
        int capacity = numSMs * (maxBlocksPerSM > 0 ? maxBlocksPerSM : 1);
        int grid_x = total_work < capacity ? total_work : capacity;
        // Round down to the nearest multiple of numSMs so the launched
        // grid maps to an integer number of full hardware waves,
        // avoiding the tail-effect partial wave (where the last wave
        // only partially occupies the SMs) reported by the profiler.
        if (grid_x >= numSMs) {
            grid_x = (grid_x / numSMs) * numSMs;
        }
        if (grid_x < 1) grid_x = 1;
        max_reduce_dim1_partial_kernel<<<grid_x, threads>>>(
            x.data_ptr<float>(), partial.data_ptr<float>(), D0, D1, D2, part_size,
            grid_y, nparts, total_work);
        int total_final = D0 * D2;
        int threads2 = 256;
        int blocks2 = (total_final + threads2 - 1) / threads2;
        max_reduce_dim1_finalize_kernel<<<blocks2, threads2>>>(
            partial.data_ptr<float>(), out.data_ptr<float>(), D0, D2, nparts);
    } else if (dim == 0) {
        out = torch::empty({D1, D2}, x.options());
        int total = D1 * D2;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        max_reduce_dim0_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), D0, D1, D2);
    } else if (dim == 2) {
        out = torch::empty({D0, D1}, x.options());
        int total = D0 * D1;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        max_reduce_dim2_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), D0, D1, D2);
    } else {
        TORCH_CHECK(false, "Unsupported dim");
    }

    return out;
}
